"""Jupyter notebooks per lab step (generated by scripts/make_notebooks.py) and the JupyterLab launcher."""
import sys
from pathlib import Path

from . import paths, services

JUPYTER_PORT = 8812
DIR = paths.ROOT / "notebooks"
BY_PAGE = {
    "views/settings_hardware.py": "00_setup_hardware.ipynb",
    "views/model_hub.py": "01_model_hub.ipynb",
    "views/data_studio.py": "02_data_studio.ipynb",
    "views/sft_training.py": "03_sft_training.ipynb",
    "views/evaluation.py": "04_evaluation.ipynb",
    "views/evals_workbench.py": "05_evals_workbench.ipynb",
    "views/human_review.py": "06_human_review.ipynb",
    "views/reward_designer.py": "07_reward_designer.ipynb",
    "views/rl_training.py": "08_rl_rlhf_training.ipynb",
    "views/human_feedback.py": "09_human_feedback.ipynb",
    "views/reward_model.py": "10_reward_model.ipynb",
    "views/compare_models.py": "11_compare_models.ipynb",
    "views/api_integrations.py": "12_api_langchain_flowise.ipynb",
    "views/rag_lab.py": "13_rag.ipynb",
    "views/agent_lab.py": "14_agents_langgraph.ipynb",
    "views/traces.py": "15_traces_monitoring.ipynb",
    "views/model_registry.py": "16_model_registry.ipynb",
}


def path_for(page):
    f = BY_PAGE.get(page)
    return DIR / f if f and (DIR / f).exists() else None


def url_for(page):
    f = BY_PAGE.get(page)
    return f"http://localhost:{JUPYTER_PORT}/lab/tree/notebooks/{f}" if f else None


def running():
    return services.port_open(JUPYTER_PORT)


def start():
    """JupyterLab bound to localhost only, no token (local teaching lab)."""
    if running():
        return None
    jl = Path(sys.executable).parent / "jupyter-lab"
    return services._spawn("jupyter", [str(jl), "--no-browser", f"--port={JUPYTER_PORT}", "--ip=127.0.0.1",
                                       f"--ServerApp.root_dir={paths.ROOT}", "--IdentityProvider.token=",
                                       "--ServerApp.password="], env={"HF_HUB_OFFLINE": "1"})
